for pp in pages:
 for index,x in enumerate(pp['sections']):
  key=(pp['path'],x['id'])
  if key in overrides:x['visual_id']=overrides[key]
  if pp['path'] in ['/about/team/','/about/news/'] and x['id']!='office':
   x['visual_id']='text-only';x['visual_description']='Открытый типографический блок имени/должности или датированного сообщения. Без случайного портрета, контактной иллюстрации и декоративного изображения.'
  if key in features:
   x['visual_id']='html-report-fields' if key==('/partners/providers/','automate-reporting') else 'html-feature-list'
   x['visual_fields']=[{'label':label,'value':None} for label in features[key]]
   x['visual_description']='HTML definition list с названиями возможностей: '+', '.join(features[key])+'. Значения, суммы, данные клиентов и фиктивные состояния не выводить. Это перечень функций, не скриншот кабинета.'
  if key in processes:
   labels,arrows=processes[key];x['visual_id']='html-process'
   x['visual_nodes']=[{'id':'n'+str(i+1),'label':label} for i,label in enumerate(labels)]
   x['visual_edges']=[{'from':'n'+str(i+1),'to':'n'+str(i+2),'label':label} for i,label in enumerate(arrows)]
   x['visual_description']='HTML-схема: '+' → '.join(labels)+'. Подписи связей: '+', '.join(arrows)+'. Показывает принцип процесса; не имитирует живую операцию и фактическую топологию.'
  if x['visual_id']=='supplier-exchange':
   x['visual_description']='Схема «Система поставщика ↔ SkyMarket → терминалы SkySend / FINGER». Данные: справочник товаров, изменения, поступление и принятие заказов, контроль доставки. Использовать специальную supplier-exchange, не схему агентского XML-шлюза.'
  if x['visual_id']=='fingerprint-scanner':x['visual_description']='Подлинное изображение сканера отпечатка из исходного каталога (scaner.png). Не подменять его общим терминалом или вымышленным устройством; не анимировать считывание биометрии.'
  if x['visual_id']=='finger-product':x['visual_description']='Подлинный экран или знак FINGER из исходника. Показать связь с браузерным кошельком; не добавлять неподтверждённые функции приложения.'
  if x['visual_id']=='download-list':x['visual_description']='HTML-реестр из data/download-catalog.json: название материала, формат, ссылка. Никакого изображения РМА или декоративного документа. Если у материала нет URL, показывать контакт поддержки вместо кнопки скачивания.'
  if pp['path']=='/about/history/' and x['visual_id']=='terminal-product':x['visual_description']='Изображение продукта использовать только как иллюстрацию типа устройства. Не подписывать современный исходный кадр как фотографию указанного исторического года. При отсутствии подходящего архивного фото оставить типографическую строку события.'
  if index==0 or x['visual_id'] in ['text-only','contact-panel','provider-logos','html-report-fields']:
   alias='none';intent='Содержимое доступно сразу в конечном состоянии.'
  elif x['visual_id'] in ['commerce-flow','supplier-exchange']:
   alias='process-step';intent='Один раз показать порядок статичных шагов; не имитировать выполнение заказа или платежа.'
  elif x['visual_id'] in ['rma-desktop','rma-android','interface-variants','infokiosk-screen','commerce-screen','terminal-screen','finger-product']:
   alias='gallery-change';intent='Увеличение подлинного изображения по явному действию; галерея только при наличии отдельных реальных кадров, без автопрокрутки.'
  else:alias='section-reveal';intent='Однократное появление содержимого секции ниже первого экрана.'
  x['motion_alias']=alias;x['motion_intent']=intent
  x['motion']=intent+' Все числа, easing, desktop/mobile и reduced-motion брать из data/motion-spec.json: contentAliases.'+alias+'.'
out={'version':1,'date':'2026-09-10','scope':'Готовые тексты 16 вторичных страниц с источниками и описанием визуала','public_copy_policy':'Публиковать title/lead/body/links. Source, visual_description, motion и editorial_decisions служебные.','motion_authority':'data/motion-spec.json contentAliases; числовые параметры только оттуда. Первый экран всегда none.','reduced_motion':'Все блоки видны сразу, transform и анимация линий выключены, переключения мгновенные.','pages':pages,'editorial_decisions':notes}
Path('data/secondary-content.json').write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding='utf-8')
report='# Вторичные страницы: тексты и постановка визуала\n\nКаноны: `docs/02-information-architecture.md`. Машинная копия: `data/secondary-content.json`. Абзацы ниже готовы для вёрстки. Источники и инструкции по визуалу служебные, не показывать их пользователю сайта.\n\nЯкорь секции равен id. Все дополнительные anchor_aliases нужно отрисовать как адресуемые элементы перед заголовком со scroll-margin-top. Ключевой смысл и ссылки видны без раскрытия.\n\nЧередовать предметный split, текстовый блок, последовательность шагов и галерею по смыслу. Не делать одинаковые карточки для всех секций. Административные страницы компактны, без полноэкранных hero. Схемы не имитируют рабочий кабинет. Для prefers-reduced-motion все блоки видны сразу, анимации выключены.\n\n'
for p in pages:
 report+='## '+p['title']+' · `'+p['path']+'`\n\n**Вводный текст:** '+p['lead']+'\n\n**Действие:** «'+p['primary_cta']['label']+'» → `'+p['primary_cta']['href']+'`.\n\n'
 for x in p['sections']:
  report+='### '+x['title']+' · `#'+x['id']+'`\n\n'+x['body']+'\n\n'
  if x['anchor_aliases']:report+='Дополнительные якоря: '+', '.join('`#'+a+'`' for a in x['anchor_aliases'])+'.\n\n'
  if x['links']:report+='Действия: '+'; '.join('«'+a['label']+'» → `'+a['href']+'`' for a in x['links'])+'.\n\n'
  report+='Визуал `'+x['visual_id']+'`: '+x['visual_description']+'\n\nАнимация: '+x['motion']+'\n\nИсточник: '+', '.join(x['source_urls'])+'.\n\n'
report+='## Решения по конфликтам\n\n'+'\n'.join('- '+n for n in notes)+'\n'
Path('docs/03b-secondary-pages.md').write_text(report,encoding='utf-8')
print('Secondary pages',len(pages),'sections',sum(len(p['sections']) for p in pages))
